class MyDropout(nn.Module):
    """实现反向缩放 Dropout (Inverted Dropout)。"""
    def __init__(self, p=0.5):
        super().__init__()
        if not 0.0 <= p < 1.0:
            raise ValueError("p must satisfy 0 <= p < 1")
        self.p = p

    def forward(self, x):
        # Step 1: 推理模式直接返回输入
        if not self.training or self.p == 0.0:
            return x

        # Step 2: 训练模式采样保留掩码
        keep_mask = (torch.rand_like(x) > self.p).to(x.dtype)

        # Step 3: 对存活元素反向缩放以保持期望不变
        out = x * keep_mask / (1.0 - self.p)
        return out

class MyEmbedding(nn.Module):
    """实现可学习的嵌入查找层 (Embedding Layer)。"""
    def __init__(self, num_embeddings, embedding_dim):
        super().__init__()

        # Step 1: 创建并注册词表嵌入矩阵
        self.weight = nn.Parameter(torch.randn(num_embeddings, embedding_dim))

    def forward(self, indices):
        # Step 2: 按整数索引收集对应嵌入向量
        out = self.weight[indices]
        return out

def clip_grad_norm(parameters, max_norm):
    """按全局 L2 范数裁剪梯度 (Gradient Norm Clipping)。"""
    # Step 1: 过滤无梯度参数并计算原始全局范数
    parameters = [param for param in parameters if param.grad is not None]
    if not parameters:
        return 0.0
    squared_norms = torch.stack([param.grad.norm().square() for param in parameters])
    total_norm = torch.sqrt(squared_norms.sum())

    # Step 2: 仅在超阈值时按统一比例缩放
    if total_norm > max_norm:
        scale = max_norm / (total_norm + 1e-6)
        for param in parameters:
            param.grad.mul_(scale)

    # Step 3: 返回裁剪前范数
    return total_norm.item()

def wsd_lr_schedule(step, warmup_steps, stable_steps, decay_steps, max_lr, min_lr=0.0):
    """实现WSD（预热-稳定-衰减）学习率调度（Warmup-Stable-Decay (WSD) LR Scheduler）。"""
    # Step 1: 在 warmup 区间按已完成步数线性升至 max_lr，随后保持峰值平台
    if step < warmup_steps:
        return float(max_lr * (step / warmup_steps))
    if step < warmup_steps + stable_steps:
        return float(max_lr)
    # Step 2: 将 decay 区间归一化到 [0,1]，用半余弦从 max_lr 平滑降至 min_lr
    total = warmup_steps + stable_steps + decay_steps
    if step <= total:
        progress = (step - warmup_steps - stable_steps) / decay_steps
        return float(min_lr + 0.5 * (max_lr - min_lr) * (1.0 + math.cos(math.pi * progress)))
    # Step 3: 超过预定训练长度后钳制为 min_lr，避免余弦周期反弹
    return float(min_lr)

class MyAdam:
    """自适应矩估计优化器 (Adam Optimizer)。"""
    def __init__(self, params, lr=1e-3, betas=(0.9, 0.999), eps=1e-8):
        self.params = list(params)
        self.lr = lr
        self.beta_1, self.beta_2 = betas
        self.eps = eps
        self.step_count = 0
        self.first_moments = [torch.zeros_like(param) for param in self.params]
        self.second_moments = [torch.zeros_like(param) for param in self.params]

    def step(self):
        # Step 1: 更新一阶矩与二阶矩
        self.step_count += 1
        with torch.no_grad():
            for index, param in enumerate(self.params):
                if param.grad is None:
                    continue
                grad = param.grad
                self.first_moments[index].mul_(self.beta_1).add_(
                    grad, alpha=1.0 - self.beta_1
                )
                self.second_moments[index].mul_(self.beta_2).addcmul_(
                    grad, grad, value=1.0 - self.beta_2
                )

                # Step 2: 校正零初始化偏差并更新参数
                first_hat = self.first_moments[index] / (
                    1.0 - self.beta_1 ** self.step_count
                )
                second_hat = self.second_moments[index] / (
                    1.0 - self.beta_2 ** self.step_count
                )
                param.sub_(self.lr * first_hat / (torch.sqrt(second_hat) + self.eps))

    def zero_grad(self):
        # Step 3: 原地清零已有梯度
        for param in self.params:
            if param.grad is not None:
                param.grad.zero_()

class MyAdamW:
    """解耦权重衰减优化器 (AdamW Optimizer)。"""
    def __init__(self, params, lr=1e-3, betas=(0.9, 0.999), eps=1e-8, weight_decay=0.01):
        self.params = list(params)
        self.lr = lr
        self.beta_1, self.beta_2 = betas
        self.eps = eps
        self.weight_decay = weight_decay
        self.first_moments = [torch.zeros_like(param) for param in self.params]
        self.second_moments = [torch.zeros_like(param) for param in self.params]
        self.step_counts = [0 for _ in self.params]

    def step(self):
        # Step 1: 对有梯度参数应用解耦权重衰减
        with torch.no_grad():
            for index, param in enumerate(self.params):
                if param.grad is None:
                    continue
                self.step_counts[index] += 1
                grad = param.grad
                param.mul_(1.0 - self.lr * self.weight_decay)

                # Step 2: 更新矩估计并进行偏差校正
                self.first_moments[index].mul_(self.beta_1).add_(
                    grad, alpha=1.0 - self.beta_1
                )
                self.second_moments[index].mul_(self.beta_2).addcmul_(
                    grad, grad, value=1.0 - self.beta_2
                )
                first_hat = self.first_moments[index] / (
                    1.0 - self.beta_1 ** self.step_counts[index]
                )
                second_hat = self.second_moments[index] / (
                    1.0 - self.beta_2 ** self.step_counts[index]
                )
                param.sub_(self.lr * first_hat / (torch.sqrt(second_hat) + self.eps))

    def zero_grad(self):
        # Step 3: 原地清零已有梯度
        for param in self.params:
            if param.grad is not None:
                param.grad.zero_()

def axial_attention(x, W_q, W_k, W_v, axis="height"):
    """二维轴向自注意力 (Axial Attention)。"""
    B, C, H, W = x.shape

    # Step 1: 将非注意力空间轴折叠进批次维
    if axis == "height":
        sequence = x.permute(0, 3, 2, 1).reshape(B * W, H, C)
    elif axis == "width":
        sequence = x.permute(0, 2, 3, 1).reshape(B * H, W, C)
    else:
        raise ValueError("axis must be 'height' or 'width'")

    # Step 2: 沿目标轴执行缩放点积注意力
    q = sequence @ W_q
    k = sequence @ W_k
    v = sequence @ W_v
    scores = q @ k.transpose(-2, -1) / (C ** 0.5)
    context = torch.softmax(scores, dim=-1) @ v

    # Step 3: 恢复 BCHW 布局
    if axis == "height":
        return context.reshape(B, W, H, C).permute(0, 3, 2, 1)
    return context.reshape(B, H, W, C).permute(0, 3, 1, 2)

def causal_conv3d(x, weight, bias=None, pad_mode='replicate'):
    """时间因果三维卷积 (Causal 3D Convolution)。"""
    k_t, k_h, k_w = weight.shape[-3:]
    temporal_pad = k_t - 1

    # Step 1: 仅在时间轴过去一侧添加复制或零填充
    if pad_mode == "replicate":
        prefix = x[:, :, :1].expand(-1, -1, temporal_pad, -1, -1)
        x_padded = torch.cat((prefix, x), dim=2)
        x_padded = F.pad(
            x_padded, (k_w // 2, k_w // 2, k_h // 2, k_h // 2, 0, 0)
        )
    elif pad_mode == "zero":
        x_padded = F.pad(
            x,
            (k_w // 2, k_w // 2, k_h // 2, k_h // 2, temporal_pad, 0),
        )
    else:
        raise ValueError("pad_mode must be 'replicate' or 'zero'")

    # Step 2: 使用无内部 padding 的三维卷积保持时间长度
    return F.conv3d(x_padded, weight, bias, stride=1, padding=0)

def einsum_operations(A, B, C, operation):
    """用爱因斯坦求和实现常见张量运算 (Einsum Operations)。"""
    # Step 1: 根据操作名选择对应的索引缩并规则
    if operation == "batch_matmul":
        return torch.einsum("bmk,bkn->bmn", A, B)
    if operation == "bilinear":
        return torch.einsum("bm,mn,bn->b", A, B, C)

    # Step 2: 用重复索引处理迹与对角线提取
    if operation == "trace":
        return torch.einsum("bii->b", A)
    if operation == "diagonal":
        return torch.einsum("ii->i", A)

    # Step 3: 保留两个独立索引以构造向量外积
    if operation == "outer":
        return torch.einsum("m,n->mn", A, B)
    raise ValueError(f"Unsupported operation: {operation}")

einsum_operations.__wrapped__ = torch.einsum

def schulman_kl_estimators(logp_policy, logp_ref, mask=None):
    """计算 Schulman 的三种 KL 估计器 (KL Estimators)。"""
    # Step 1: 构造策略相对参考模型的逐 token 对数比
    log_ratio = logp_policy - logp_ref

    # Step 2: 计算 k1、k2 与非负 k3
    estimators = (
        log_ratio,
        0.5 * log_ratio.square(),
        torch.exp(-log_ratio) + log_ratio - 1.0,
    )

    # Step 3: 使用普通均值或统一掩码均值归约
    if mask is None:
        return tuple(value.mean() for value in estimators)
    denominator = mask.sum().clamp(min=1.0)
    return tuple((value * mask).sum() / denominator for value in estimators)

class LionOptimizer:
    """实现符号动量优化器 (Lion Optimizer)。"""

    def __init__(self, params, lr=1e-4, betas=(0.9, 0.99), weight_decay=0.0):
        self.params = list(params)
        self.lr = lr
        self.beta1, self.beta2 = betas
        self.weight_decay = weight_decay
        self.momentum = [torch.zeros_like(param) for param in self.params]

    def step(self):
        # Step 1: 在无梯度环境应用解耦权重衰减
        with torch.no_grad():
            for index, param in enumerate(self.params):
                if param.grad is None:
                    continue
                grad = param.grad
                param.mul_(1.0 - self.lr * self.weight_decay)

                # Step 2: 用旧动量与当前梯度的插值符号更新参数
                update = self.beta1 * self.momentum[index] + (1.0 - self.beta1) * grad
                param.add_(torch.sign(update), alpha=-self.lr)

                # Step 3: 参数更新后再刷新持久动量
                self.momentum[index].mul_(self.beta2).add_(grad, alpha=1.0 - self.beta2)

    def zero_grad(self):
        for param in self.params:
            if param.grad is not None:
                param.grad.zero_()

class StochasticDepth(nn.Module):
    """实现随机深度（DropPath）（Stochastic Depth (DropPath)）。"""

    def __init__(self, drop_prob=0.1):
        # Step 1: 保存路径丢弃率及其对应的 Bernoulli 保留概率
        super().__init__()
        self.drop_prob = drop_prob
        self.keep_prob = 1.0 - drop_prob

    def forward(self, x, f_x):
        # Step 2: 训练时为每个样本独立决定是否保留整条残差分支
        if self.training:
            if self.drop_prob == 0.0:
                return x + f_x
            shape = (x.shape[0],) + (1,) * (x.ndim - 1)
            mask = torch.rand(shape, device=x.device) < self.keep_prob
            return x + f_x * mask
        else:
            # Step 3: 推理时用保留概率缩放分支以匹配训练随机输出的期望
            return x + self.keep_prob * f_x

class SimpleBPE:
    """简单字节对编码器 (Byte-Pair Encoding)。"""
    def __init__(self):
        self.merges = []

    def train(self, corpus, num_merges):
        # Step 1: 统计带词尾标记的初始词表
        vocab = {}
        for word in corpus:
            symbols = tuple(word) + ("</w>",)
            vocab[symbols] = vocab.get(symbols, 0) + 1
        self.merges = []

        # Step 2: 反复选择频率最高的相邻符号对并合并
        for _ in range(num_merges):
            pair_counts = {}
            for symbols, frequency in vocab.items():
                for index in range(len(symbols) - 1):
                    pair = (symbols[index], symbols[index + 1])
                    pair_counts[pair] = pair_counts.get(pair, 0) + frequency
            if not pair_counts:
                break
            best_pair = max(pair_counts, key=pair_counts.get)
            self.merges.append(best_pair)
            next_vocab = {}
            for symbols, frequency in vocab.items():
                merged = []
                index = 0
                while index < len(symbols):
                    if (
                        index + 1 < len(symbols)
                        and (symbols[index], symbols[index + 1]) == best_pair
                    ):
                        merged.append(symbols[index] + symbols[index + 1])
                        index += 2
                    else:
                        merged.append(symbols[index])
                        index += 1
                next_vocab[tuple(merged)] = frequency
            vocab = next_vocab

    def encode(self, text):
        # Step 3: 按训练顺序将合并规则应用到每个单词
        tokens = []
        for word in text.split():
            symbols = list(word) + ["</w>"]
            for left, right in self.merges:
                index = 0
                while index < len(symbols) - 1:
                    if symbols[index] == left and symbols[index + 1] == right:
                        symbols = (
                            symbols[:index]
                            + [left + right]
                            + symbols[index + 2:]
                        )
                    else:
                        index += 1
            tokens.extend(symbols)
        return tokens
